"""Observed MCP tool extraction from tracker events for tool-call evaluation."""

from __future__ import annotations

from collections.abc import Iterable

from pydantic import BaseModel, ConfigDict

from rasa.builder.copilot.mcp_server.tools.event_ledger import (
    is_user_relevant_tool_run,
    split_into_turns,
    user_message_from_turn_events,
)
from rasa.shared.core.events import (
    Event,
    McpToolExecuted,
    ToolExecuted,
)

ToolRunEvent = McpToolExecuted | ToolExecuted


class ObservedTool(BaseModel):
    """One observed MCP tool call with turn context for scoring and reports."""

    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)

    turn_index: int
    event: ToolRunEvent
    user_message: str = ""


def get_tools_from_events(events: Iterable[Event]) -> list[ObservedTool]:
    """Collect observed tool-run events with turn index and user message.

    Framework calls other than ``search_knowledge`` and ``cannot_help`` are
    omitted. CALM trackers record ``McpToolExecuted``; Mantle trackers record
    ``ToolExecuted``. Both are kept when user-relevant.
    """
    events_list = list(events)
    if not events_list:
        return []

    observed_tools: list[ObservedTool] = []
    for turn_index, turn_events in split_into_turns(events_list):
        user_message = ""
        if turn_index > 0:
            message = user_message_from_turn_events(turn_events)
            if message:
                user_message = message
        for event in turn_events:
            if not isinstance(event, (McpToolExecuted, ToolExecuted)):
                continue
            if not is_user_relevant_tool_run(event):
                continue
            observed_tools.append(
                ObservedTool(
                    turn_index=turn_index,
                    event=event,
                    user_message=user_message,
                )
            )

    return observed_tools


def turn_indices(observed_tools: list[ObservedTool]) -> list[int]:
    """Return sorted turn indices that have at least one observed tool."""
    return sorted({tool.turn_index for tool in observed_tools})


def events_on_turn(
    turn_index: int, observed_tools: list[ObservedTool]
) -> list[ToolRunEvent]:
    """Return tool events observed on one turn."""
    return [tool.event for tool in observed_tools if tool.turn_index == turn_index]


def user_message_for_turn(turn_index: int, observed_tools: list[ObservedTool]) -> str:
    """Return the user message for a turn from any observed tool on that turn."""
    for tool in observed_tools:
        if tool.turn_index == turn_index and tool.user_message:
            return tool.user_message
    return ""
